verus! {
    fn solve(n: u8) -> (r: u8)
        ensures
            r as int == popcount(n as int)
        ensures
            r <= 8
    {
        let mut count: u8 = 0;
        let mut x = n;
        while x != 0 {
            count = count + (x & 1);
            x = x >> 1;
        }
        count
    }

    #[spec]
    fn popcount(n: int) -> int {
        if n == 0 {
            0
        } else {
            (n % 2) + popcount(n / 2)
        }
    }
}